from __future__ import annotations

import base64
import hashlib
import zlib

# Generated only after the governed private-beta activation build passes.
# Runtime consumers see provider-neutral JSON through the frozen schemas.

ACTIVATION_WORKFLOW_RUN_ID = 35124981014
ACTIVATION_BUNDLE_SHA256 = '31051dd15843e7b4bf62ca4a6ea94d9f9337b64d73fc35a49a892d7591922695'
ACTIVATION_ARTIFACT_SHA256 = {'frozen_i1_h12.json': 'ab3761ef85e8b8bb6811bb9e2bc3728d79f8e664058200963bc720a901c1b591', 'frozen_i1_h3.json': 'f34aa09284f207a5619857a8a066424880f8605344c6aaca56140c1afeeee2bd', 'current_i1_facts_2026.json': '4ee0719c40dfc067c23e76d09dda8e501fa95014dbc2162d10ee571882f07edf', 'private_beta_activation_build_report.json': 'cd58e6f469e010c7f717cff2f466cb8b7a8d8ef554406a1e55ed4b2959f385fb'}
_COMPRESSED_ARTIFACTS = {'frozen_i1_h12.json': '', 'frozen_i1_h3.json': '', 'current_i1_facts_2026.json': '', 'private_beta_activation_build_report.json': ''}

def activation_artifact_text(name: str) -> str:
    try:
        encoded = _COMPRESSED_ARTIFACTS[name]
        expected = ACTIVATION_ARTIFACT_SHA256[name]
    except KeyError as exc:
        raise ValueError(f"missing private-beta activation artifact: {name}") from exc
    raw = zlib.decompress(base64.b64decode(encoded, validate=True))
    actual = hashlib.sha256(raw).hexdigest()
    if actual != expected:
        raise ValueError(f"private-beta activation artifact digest mismatch: {name}")
    return raw.decode("utf-8")
